SELECT a.hadm_id, a.stay_id, p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, i.icustay_id, i.first_careunit, i.last_careunit, i.intime, i.outtime, i.los, l.itemid, l.value, l.valuenum, l.valueuom, s.subject_id, s.hadm_id, s.stay_id, s.icustay_id, s.first_careunit, s.last_careunit, s.intime, s.outtime, s.los, d.diagnosis_id, d.diagnosis_code, d.diagnosis_name, d.diagnosis_type, d.diagnosis_category, d.diagnosis_severity, d.diagnosis_mortality, m.micr_event_id, m.micr_specimen_id, m.micr_order_provider_id, m.micr_chartdate, m.micr_charttime, m.micr_storedate, m.micr_storetime, m.micr_value, m.micr_value_num, m.micr_value_uom, o.order_id, o.order_provider_id, o.order_date, o.order_time, o.order_status, o.order_type, o.order_subtype, o.order_seq_num, r.room_id, r.room_name, r.room_type, r.room_status, r.room_capacity, r.room_bed_count, r.room_bed_type, r.room_bed_status, r.room_last_updated, r.room_last_updated_by, r.room_last_updated_date, r.room_last_updated_time, c.caregiver_id, c.caregiver_first_name, c.caregiver_last_name, c.caregiver_title, c.caregiver_status, c.caregiver_type, c.caregiver_specialty, c.caregiver_start_date, c.caregiver_end_date, c.caregiver_last_updated, c.caregiver_last_updated_by, c.caregiver_last_updated_date, c.caregiver_last_updated_time FROM admissions a JOIN patients p ON a.subject_id = p.subject_id JOIN icustays i ON a.stay_id = i.icustay_id JOIN chartevents l ON a.stay_id = l.stay_id AND a.subject_id = l.subject_id JOIN diagnoses_icd d ON a.stay_id = d.stay_id AND a.subject_id = d.subject_id JOIN microbiologyevents m ON a.stay_id = m.stay_id AND a.subject_id = m.subject_id JOIN orders o ON a.stay_id = o.order_id AND a.subject_id = o.order_provider_id JOIN rooms r ON a.first_careunit = r.room_id AND a.last_careunit = r.room_id JOIN caregivers c ON a.first_careunit = c.caregiver_id AND a.last_careunit = c.caregiver_id WHERE p.gender = 'M' AND p.anchor_age BETWEEN 56 AND 66 AND l.itemid = 848077 AND l.valueuom = 'mmHg' AND l.value BETWEEN 65 AND 85;